.box {
  width: 200px;
  padding: 20px;
  border: 5px solid;
  box-sizing: border-box; /* width에 padding·border 포함 → 실제 content는 150px */
}

.row {
  display: flex;
  justify-content: space-between; /* 주축(가로) 정렬 */
  align-items: center;            /* 교차축(세로) 정렬 */
}

.grid {
  display: grid;
  grid-template-columns: 1fr 2fr; /* 남은 공간을 1:2로 분배 */
}
